window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8eb13d9e0c60952d"]={"versions": [{"id": "FIG-8eb13d9e0c60952d", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Modulare System- und Schnittstellenarchitektur / Blockdiagramm gemäß ETSI ES 201 873-5 (TTCN-3 Control Interface, TCI) und ETSI ES 201 873-6 (TTCN-3 Runtime Interface, TRI).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Conformance Testing (<code>AUTOSAR_CTSpec_Execution_Constraints</code>, Doc ID 284, Releases R3.0.7 / R3.1.5).</li>\n<li><strong>Technischer Zweck:</strong> Referenzarchitektur eines standardisierten TTCN-3-Testsystems zur Verifikation von Ausführungszeitbeschränkungen (<em>Execution Constraints</em>), Task-Scheduling, OS-/RTE-Eigenschaften und deterministischem Timing-Verhalten einer AUTOSAR-Implementierung. Sie entkoppelt die abstrakte Testlogik strikt von Codierung, Testmanagement, physikalischer Hardware-Adaption und Zielplattform.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Test System User:</strong> Externe Entität (Testingenieur, CI/CD-Runner oder automatisiertes Test-Framework), die Testkampagnen konfiguriert, initiiert und überwacht.</li>\n<li><strong>TM (Test Management – TCI-TM):</strong> Verwaltet Testsuiten, Testfall-Selektion, Modulparameter, Ablaufsteuerung sowie zentrales Logging und Verdict-Konsolidierung (<code>none</code>, <code>pass</code>, <code>inconclusive</code>, <code>fail</code>, <code>error</code>).</li>\n<li><strong>CH (Component Handling – TCI-CH):</strong> Steuert die Prozess- und Thread-Verteilung der TTCN-3-Laufzeitumgebung; instanziiert, synchronisiert und terminiert parallele Testkomponenten (<em>PTC</em>) und die Hauptkomponente (<em>MTC</em>).</li>\n<li><strong>CD (Coder/Decoder – TCI-CD):</strong> Bidirektionale Transformation zwischen den abstrakten TTCN-3-Datentypen (z. B. strukturierte Records, Signale) der Test Executable und den konkreten binären Bitstreams/Frames des SUT (PDU-Serialisierung, Endianness, Padding).</li>\n<li><strong>TE (TTCN-3 Executable):</strong> Zentraler Ausführungskern; führt kompilierte/interpretierte Testfälle aus, evaluiert Guards, verwaltet abstrakte Ports/Timer und steuert den Kontrollfluss.</li>\n<li><strong>SA (SUT Adapter – TRI-SA):</strong> Realisiert den hardwarenahen Ein-/Ausgangskanal zum Target. Bildet TTCN-3-Nachrichten sowie Funktions-/Prozeduraufrufe auf physikalische Schnittstellen (CAN, LIN, FlexRay, Ethernet, GPIO, Debug-/Trace-Ports) ab.</li>\n<li><strong>PA (Platform Adapter – TRI-PA):</strong> Kapselt plattformspezifische Basisfunktionen der Testumgebung, insbesondere hochauflösende Hardware-Timer, Systemuhren und Aufrufe externer C/C++-Hilfsfunktionen (<em>external functions</em>).</li>\n<li><strong>SUT (System Under Test):</strong> Das zu prüfende AUTOSAR-System (z. B. vollständiges Steuergerät/ECU, BSW-Stack, OS/RTE oder virtualisierte vECU/SiL-Instanz).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Parametrierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Test System User startet Testlauf über <strong>TM</strong>.</li>\n<li><strong>TM</strong> lädt Testparameter, initialisiert <strong>TE</strong> und weist <strong>CH</strong> an, den <em>MTC</em> zu instanziieren.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Stimulation & SUT-Interaktion (synchron / asynchron):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>TE</strong> triggert Testaktion (Senden von Nachrichten oder Methodenaufrufen).</li>\n<li>Abstrakte Testdaten werden synchron an <strong>CD</strong> übergeben und in binäre Zielformate serialisiert.</li>\n<li><strong>TE</strong> übergibt serialisierte PDUs via TRI an <strong>SA</strong>, welcher diese physisch auf den Bus bzw. die I/O-Pins des <strong>SUT</strong> legt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Plattform- & Timing-Kontrolle:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei zeitkritischen Tests startet <strong>TE</strong> Timer über <strong>PA</strong>.</li>\n<li><strong>PA</strong> überwacht Fristen (z. B. Timeouts, Execution-Budget-Grenzen) hardwarenah und meldet Timeout-Events asynchron an <strong>TE</strong> zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ergebnisempfang & Auswertung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>SUT</strong> sendet Antwortframes oder Triggersignale.</li>\n<li><strong>SA</strong> erfasst Rohdaten asynchron, <strong>CD</strong> dekodiert diese in abstrakte TTCN-3-Typen.</li>\n<li><strong>TE</strong> führt Pattern-Matching gegen Soll-Erwartungsmuster durch.</li>\n<li>Verletzungen von Constraints führen zum Abbruch des Testschritts und zur Zuweisung des Verdicts <code>fail</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss & Dekonstruktion:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>CH</strong> terminiert verbleibende PTCs geordnet.</li>\n<li><strong>TM</strong> liest Trace-Logs aus <strong>TE</strong> aus und exportiert den Testreport an den Test System User.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Black-Box-/Gray-Box-Fokus:</strong> Die Spezifikation verlangt die Verifikation von <em>Execution Constraints</em> an externen oder standardisierten Schnittstellen, ohne produktiven BSW-Code mit proprietären Test-Hooks zu instrumentieren.</li>\n<li><strong>Echtzeitanforderung an SA und PA:</strong> Um Ausführungszeiten, Interrupt-Latenzen und Jitter normativ zu erfassen, müssen <strong>PA</strong> (Hardware-Timestamping) und <strong>SA</strong> eine signifikant höhere Zeitauflösung und geringere Latenz aufweisen als die im SUT spezifizierten Zeitschranken (z. B. Sub-Mikrosekundenbereich bei Task-Wechseln und Preemption-Checks).</li>\n<li><strong>Datendefinitions-Parität (CD vs. ARXML/FIBEX):</strong> Bit-Order, Bit-Positioning, Alignment und Datentyp-Mapping im <strong>CD</strong> müssen absolut deckungsgleich mit den AUTOSAR-Systembeschreibungen (ARXML) des SUT sein. Unstimmigkeiten in Serialisierung/Deserialisierung führen zu Scheitern der Conformance-Tests unabhängig von der korrekten internen BSW-Logik.</li>\n<li><strong>Deterministisches Scheduling im SUT:</strong> Entwickler von BSW-Stacks, OS-Tasks und CDDs müssen sicherstellen, dass konfigurierte WCET- und Blocking-Zeiten auch unter Worst-Case-Stimulation durch den <strong>SA</strong> eingehalten werden, da das Testsystem Timing-Verletzungen deterministisch als Non-Conformance flagged.</li>\n</ul>"}, {"id": "FIG-27d5cdd42cf15663", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Modulare System- und Schnittstellenarchitektur / Blockdiagramm gemäß ETSI ES 201 873-5 (TTCN-3 Control Interface, TCI) und ETSI ES 201 873-6 (TTCN-3 Runtime Interface, TRI).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Conformance Testing (<code>AUTOSAR_CTSpec_Execution_Constraints</code>, Doc ID 284, Releases R3.0.7 / R3.1.5).</li>\n<li><strong>Technischer Zweck:</strong> Referenzarchitektur eines standardisierten TTCN-3-Testsystems zur Verifikation von Ausführungszeitbeschränkungen (<em>Execution Constraints</em>), Task-Scheduling, OS-/RTE-Eigenschaften und deterministischem Timing-Verhalten einer AUTOSAR-Implementierung. Sie entkoppelt die abstrakte Testlogik strikt von Codierung, Testmanagement, physikalischer Hardware-Adaption und Zielplattform.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Test System User:</strong> Externe Entität (Testingenieur, CI/CD-Runner oder automatisiertes Test-Framework), die Testkampagnen konfiguriert, initiiert und überwacht.</li>\n<li><strong>TM (Test Management – TCI-TM):</strong> Verwaltet Testsuiten, Testfall-Selektion, Modulparameter, Ablaufsteuerung sowie zentrales Logging und Verdict-Konsolidierung (<code>none</code>, <code>pass</code>, <code>inconclusive</code>, <code>fail</code>, <code>error</code>).</li>\n<li><strong>CH (Component Handling – TCI-CH):</strong> Steuert die Prozess- und Thread-Verteilung der TTCN-3-Laufzeitumgebung; instanziiert, synchronisiert und terminiert parallele Testkomponenten (<em>PTC</em>) und die Hauptkomponente (<em>MTC</em>).</li>\n<li><strong>CD (Coder/Decoder – TCI-CD):</strong> Bidirektionale Transformation zwischen den abstrakten TTCN-3-Datentypen (z. B. strukturierte Records, Signale) der Test Executable und den konkreten binären Bitstreams/Frames des SUT (PDU-Serialisierung, Endianness, Padding).</li>\n<li><strong>TE (TTCN-3 Executable):</strong> Zentraler Ausführungskern; führt kompilierte/interpretierte Testfälle aus, evaluiert Guards, verwaltet abstrakte Ports/Timer und steuert den Kontrollfluss.</li>\n<li><strong>SA (SUT Adapter – TRI-SA):</strong> Realisiert den hardwarenahen Ein-/Ausgangskanal zum Target. Bildet TTCN-3-Nachrichten sowie Funktions-/Prozeduraufrufe auf physikalische Schnittstellen (CAN, LIN, FlexRay, Ethernet, GPIO, Debug-/Trace-Ports) ab.</li>\n<li><strong>PA (Platform Adapter – TRI-PA):</strong> Kapselt plattformspezifische Basisfunktionen der Testumgebung, insbesondere hochauflösende Hardware-Timer, Systemuhren und Aufrufe externer C/C++-Hilfsfunktionen (<em>external functions</em>).</li>\n<li><strong>SUT (System Under Test):</strong> Das zu prüfende AUTOSAR-System (z. B. vollständiges Steuergerät/ECU, BSW-Stack, OS/RTE oder virtualisierte vECU/SiL-Instanz).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Parametrierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Test System User startet Testlauf über <strong>TM</strong>.</li>\n<li><strong>TM</strong> lädt Testparameter, initialisiert <strong>TE</strong> und weist <strong>CH</strong> an, den <em>MTC</em> zu instanziieren.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Stimulation & SUT-Interaktion (synchron / asynchron):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>TE</strong> triggert Testaktion (Senden von Nachrichten oder Methodenaufrufen).</li>\n<li>Abstrakte Testdaten werden synchron an <strong>CD</strong> übergeben und in binäre Zielformate serialisiert.</li>\n<li><strong>TE</strong> übergibt serialisierte PDUs via TRI an <strong>SA</strong>, welcher diese physisch auf den Bus bzw. die I/O-Pins des <strong>SUT</strong> legt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Plattform- & Timing-Kontrolle:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei zeitkritischen Tests startet <strong>TE</strong> Timer über <strong>PA</strong>.</li>\n<li><strong>PA</strong> überwacht Fristen (z. B. Timeouts, Execution-Budget-Grenzen) hardwarenah und meldet Timeout-Events asynchron an <strong>TE</strong> zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ergebnisempfang & Auswertung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>SUT</strong> sendet Antwortframes oder Triggersignale.</li>\n<li><strong>SA</strong> erfasst Rohdaten asynchron, <strong>CD</strong> dekodiert diese in abstrakte TTCN-3-Typen.</li>\n<li><strong>TE</strong> führt Pattern-Matching gegen Soll-Erwartungsmuster durch.</li>\n<li>Verletzungen von Constraints führen zum Abbruch des Testschritts und zur Zuweisung des Verdicts <code>fail</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss & Dekonstruktion:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>CH</strong> terminiert verbleibende PTCs geordnet.</li>\n<li><strong>TM</strong> liest Trace-Logs aus <strong>TE</strong> aus und exportiert den Testreport an den Test System User.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Black-Box-/Gray-Box-Fokus:</strong> Die Spezifikation verlangt die Verifikation von <em>Execution Constraints</em> an externen oder standardisierten Schnittstellen, ohne produktiven BSW-Code mit proprietären Test-Hooks zu instrumentieren.</li>\n<li><strong>Echtzeitanforderung an SA und PA:</strong> Um Ausführungszeiten, Interrupt-Latenzen und Jitter normativ zu erfassen, müssen <strong>PA</strong> (Hardware-Timestamping) und <strong>SA</strong> eine signifikant höhere Zeitauflösung und geringere Latenz aufweisen als die im SUT spezifizierten Zeitschranken (z. B. Sub-Mikrosekundenbereich bei Task-Wechseln und Preemption-Checks).</li>\n<li><strong>Datendefinitions-Parität (CD vs. ARXML/FIBEX):</strong> Bit-Order, Bit-Positioning, Alignment und Datentyp-Mapping im <strong>CD</strong> müssen absolut deckungsgleich mit den AUTOSAR-Systembeschreibungen (ARXML) des SUT sein. Unstimmigkeiten in Serialisierung/Deserialisierung führen zu Scheitern der Conformance-Tests unabhängig von der korrekten internen BSW-Logik.</li>\n<li><strong>Deterministisches Scheduling im SUT:</strong> Entwickler von BSW-Stacks, OS-Tasks und CDDs müssen sicherstellen, dass konfigurierte WCET- und Blocking-Zeiten auch unter Worst-Case-Stimulation durch den <strong>SA</strong> eingehalten werden, da das Testsystem Timing-Verletzungen deterministisch als Non-Conformance flagged.</li>\n</ul>"}], "trans": [{"from": "FIG-8eb13d9e0c60952d", "to": "FIG-27d5cdd42cf15663", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
